import type { Preview } from '@storybook/react-vite';
import { Global } from '@emotion/react';
import { initialize, mswLoader } from 'msw-storybook-addon';
import { MemoryRouter } from 'react-router-dom';
import { resetStyles, bodyStyles } from '../src/components/styles/globalStyles';
import { fontStyles } from '../src/components/styles/fonts';
import { ToastProvider } from '../src/context/toast';
import { mswHandlers } from './msw-handlers';

initialize({
  onUnhandledRequest: 'bypass',
});

const preview: Preview = {
  decorators: [
    (Story) => (
      <>
        <Global styles={[resetStyles, bodyStyles, fontStyles]} />
        <MemoryRouter>
          <ToastProvider>
            <Story />
          </ToastProvider>
        </MemoryRouter>
      </>
    ),
  ],
  loaders: [mswLoader],
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    a11y: {
      test: 'todo',
    },
    msw: {
      handlers: mswHandlers,
    },
  },
};

export default preview;

import { http, HttpResponse } from "msw";

export const mswHandlers = [
  // AuthProvider checks authentication on mount by posting to /graphql/query
  http.post("*/graphql/query", () =>
    HttpResponse.json({
      data: {
        user: {
          userId: "mock-user-id",
        },
      },
    }),
  ),
  // AuthProvider local login endpoint
  http.post("*/login", () => new HttpResponse(null, { status: 200 })),
  // AuthProvider logout endpoint
  http.get("*/logout", () => new HttpResponse(null, { status: 200 })),
];

import type { StorybookConfig } from '@storybook/react-vite';

const config: StorybookConfig = {
  stories: [
    '../src/**/*.mdx',
    '../src/**/*.stories.@(js|jsx|mjs|ts|tsx)',
    './eval-support/*.mdx',
  ],
  addons: [
    '@chromatic-com/storybook',
    '@storybook/addon-vitest',
    '@storybook/addon-a11y',
    '@storybook/addon-docs',
    '@storybook/addon-onboarding',
  ],
  framework: '@storybook/react-vite',
  staticDirs: ['../public'],
};

export default config;

import { storybookTest } from "@storybook/addon-vitest/vitest-plugin";
import react from "@vitejs/plugin-react";
import { playwright } from "@vitest/browser-playwright";
import tsconfigPaths from "vite-tsconfig-paths";
import { defineConfig } from "vitest/config";
import path from "node:path";
import { fileURLToPath } from "node:url";

const dirname =
  typeof __dirname !== "undefined"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));
const playwrightProviderOptions =
  process.env.STORYBOOK_TEST_SCREENSHOTS === "true"
    ? {
        contextOptions: {
          deviceScaleFactor: 2,
          viewport: { width: 393, height: 852 },
          isMobile: true,
          hasTouch: true,
          userAgent:
            "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
        },
      }
    : {};

// More info at: https://storybook.js.org/docs/next/writing-tests/integrations/vitest-addon
export default defineConfig({
  plugins: [
    tsconfigPaths(),
    react({
      babel: {
        plugins: ["import-graphql"],
      },
    }),
  ],
  resolve: {
    extensions: [".mjs", ".js", ".ts", ".jsx", ".tsx", ".json"],
    alias: {
      "@emotion/server/create-instance": path.join(
        dirname,
        ".storybook/emotion-server-stub.ts",
      ),
      "@emotion/server": path.join(
        dirname,
        ".storybook/emotion-server-stub.ts",
      ),
    },
  },
  define: {
    "process.env": JSON.stringify({}),
  },
  test: {
    reporters: ["default", ...(process.env.CI === "true" ? ["junit"] : [])],
    outputFile: {
      junit: "./bin/vitest/junit.xml",
    },
    projects: [
      {
        extends: true,
        test: {
          environment: "jsdom",
          globals: true,
          setupFiles: "./config/vitest/setupTests.ts",
          globalSetup: "./config/vitest/global-setup.ts",
        },
      },
      {
        extends: true,
        plugins: [
          // The plugin will run tests for the stories defined in your Storybook config
          // See options at: https://storybook.js.org/docs/next/writing-tests/integrations/vitest-addon#storybooktest
          storybookTest({
            configDir: path.join(dirname, ".storybook"),
          }),
        ],
        test: {
          name: "storybook",
          browser: {
            enabled: true,
            headless: true,
            provider: playwright(playwrightProviderOptions),
            instances: [
              {
                browser: "chromium",
              },
            ],
          },
        },
      },
    ],
  },
});

