 41→      if (
 42→        popoverRef.current &&
 43→        !popoverRef.current.contains(event.target as Node) &&
 44→        (!refEl ||
 45→          (refEl &&
 46→            refEl instanceof HTMLElement &&
 47→            refEl.contains(event.target as Node)))
 48→      ) {
 49→        onClose();
 50→        setOpen(false);
 51→      }
 52→    };
 53→
 54→    if (typeof window !== "undefined" && open) {
 55→      document.addEventListener("mousedown", handleClickOutside);
 56→      return () => {
 57→        document.removeEventListener("mousedown", handleClickOutside);
 58→      };
 59→    }
 60→  }, [open, onClose, setOpen, refEl]);
 61→
 62→  return (
 63→    <Tooltip
 64→      onClose={onClose}
 65→      open={open}
 66→      refEl={refEl}
 67→      setOpen={setOpen}
 68→      triggerEvent="click"
 69→      {...props}
 70→    >
 71→      <ContentWrapper ref={popoverRef}>
 72→        {children}
 73→        <ButtonWrapper>
 74→          <Button
 75→            as="button"
 76→            onClick={() => {
 77→              onClose();
 78→              setOpen(false);
 79→            }}
 80→            size="small"
 81→          >
 82→            Cancel
 83→          </Button>
 84→          <Button
 85→            as="button"
 86→            disabled={confirmDisabled}
 87→            onClick={(e) => {
 88→              onConfirm(e);
 89→              setOpen(false);
 90→            }}
 91→            size="small"
 92→            variant="primary"
 93→          >
 94→            {confirmText}
 95→          </Button>
 96→        </ButtonWrapper>
 97→      </ContentWrapper>
 98→    </Tooltip>
 99→  );
100→};
